export const stationChapters: Chapter[] = stationChapterDrafts.map(
  ({ title, paragraphs, visual, visualAfter }, index) => {
    const number = index + 1;
    const wordCount = paragraphs.join(" ").trim().split(/\s+/).length;

    return {
      number,
      title,
      readingMinutes: Math.max(3, Math.ceil(wordCount / 190)),
      paragraphs,
      visuals: [
        {
          id: `la-estacion-de-las-317-capitulo-${number}-imagen-1`,
          afterParagraph: visualAfter ?? Math.ceil(paragraphs.length / 2),
          alt: `Escena del capítulo ${number}, ${title}, de La estación de las 3:17`,
          prompt: visual,
          aspectRatio: "16/9",
          status: "pending",
          url: null,
        },
      ],
    };
  },
);

export const stationReadingMinutes = stationChapters.reduce(
  (total, chapter) => total + chapter.readingMinutes,
  0,
);
